package org.example.service;
import org.example.api.master.MasterApiClient; import org.example.config.ConfigManager; import org.example.dao.LookupDAO; import org.example.model.Lookup; import java.util.*;
public class LookupService {private final LookupDAO dao=new LookupDAO();private final MasterApiClient api=new MasterApiClient();private boolean useApi(){return ConfigManager.isApiDataEnabled();}
 public void save(Lookup l){if(useApi())api.saveLookup(l);else dao.save(l);} public void update(Lookup l){if(useApi())api.updateLookup(l);else dao.update(l);} public void delete(Lookup l){if(l==null)return;if(useApi())api.deleteLookup(l.getId(),l.getRowVersion());else dao.delete(l);} public void delete(int id){if(useApi())throw new IllegalStateException("Managed-server lookup delete requires the loaded row version.");else dao.delete(id);} public void setActive(Lookup l,boolean active){if(l==null)return;l.setActive(active);if(useApi()){var saved=api.setLookupActive(l.getId(),active,l.getRowVersion());l.setRowVersion(saved.rowVersion());}else dao.update(l);} public List<Lookup> getByType(String t){return useApi()?api.lookups(t):dao.getByType(t);} public List<Lookup> getByCategoryCode(String c){return useApi()?api.lookupsByCategoryCode(c):dao.getByCategoryCode(c);} public List<String> getValues(String t){return useApi()?api.lookupValues(t):dao.getValues(t);} public List<String> getValuesByCategoryCode(String c){return useApi()?api.lookupValuesByCategoryCode(c):dao.getValuesByCategoryCode(c);} public String generateNextCode(String t){return useApi()?api.nextLookupCode(t):dao.generateNextCode(t);} }
